dashboard.definition:
{
  "title": "KO Diff — Test Harness",
  "description": "Exercises the Dashboard Diff (Schematic) viz against the bundled test fixtures, inside Dashboard Studio.",
  "visualizations": {
    "md_intro": {
      "type": "splunk.markdown",
      "options": { "markdown": "# KO Diff — Test Harness\nThe **Dashboard Diff (Schematic)** viz running inside Dashboard Studio, comparing two versions of a dashboard. Below: a Simple XML pair and a Dashboard Studio pair from the bundled fixtures." }
    },
    "md_sxml": { "type": "splunk.markdown", "options": { "markdown": "## Simple XML pair — Network Health v1 → v2\nExpect: Latency & SNR **changed**, Throughput **added**." } },
    "viz_sxml": { "type": "ko_history.dashboard_preview_ds", "dataSources": { "primary": "ds_sxml" } },
    "md_ds": { "type": "splunk.markdown", "options": { "markdown": "## Dashboard Studio pair — Service Overview v1 → v2\nExpect: Latency **moved**, Notes **changed**, Errors **removed**, Saturation **added**." } },
    "viz_ds": { "type": "ko_history.dashboard_preview_ds", "dataSources": { "primary": "ds_ds" } }
  },
  "dataSources": {
    "ds_sxml": {
      "type": "ds.search",
      "options": { "query": "| rest /servicesNS/-/-/data/ui/views splunk_server=local | search title IN (ko_diff_sxml_v1, ko_diff_sxml_v2) | eval role=if(title=\"ko_diff_sxml_v1\",\"baseline\",\"target\") | rename eai:data as data | table role title data" }
    },
    "ds_ds": {
      "type": "ds.search",
      "options": { "query": "| rest /servicesNS/-/-/data/ui/views splunk_server=local | search title IN (ko_diff_ds_v1, ko_diff_ds_v2) | eval role=if(title=\"ko_diff_ds_v1\",\"baseline\",\"target\") | rename eai:data as data | table role title data" }
    }
  },
  "layout": {
    "type": "absolute",
    "options": { "width": 2000, "height": 3000 },
    "structure": [
      { "item": "md_intro", "type": "block", "position": { "x": 0, "y": 0, "w": 2000, "h": 120 } },
      { "item": "md_sxml", "type": "block", "position": { "x": 0, "y": 140, "w": 2000, "h": 80 } },
      { "item": "viz_sxml", "type": "block", "position": { "x": 0, "y": 240, "w": 2000, "h": 1200 } },
      { "item": "md_ds", "type": "block", "position": { "x": 0, "y": 1480, "w": 2000, "h": 80 } },
      { "item": "viz_ds", "type": "block", "position": { "x": 0, "y": 1580, "w": 2000, "h": 1380 } }
    ]
  }
}
